q = queue.Queue(maxsize=256)            # the bound: block or shed

def producer(src):
    for item in src:
        q.put(item)                      # blocks while the consumer is behind
        # or: q.put_nowait(item) / queue.Full -> shed explicitly

def consumer():
    while (item := q.get()) is not None: # sentinel terminates the loop
        handle(item)
        q.task_done()
